+		strings.Contains(lineLower, "twin stable") || strings.Contains(lineLower, "certify-azure") ||
+		strings.Contains(lineLower, "image_format") || strings.Contains(lineLower, "ova_route") ||
+		strings.Contains(lineLower, "skip_image_wait") || strings.Contains(lineLower, "publish_certified_azure")
+}
