+// prefilterUnsound returns the rules whose regex matches the line while the
+// rule's prefilter would have skipped it (empty when every prefilter is sound).
+func prefilterUnsound(line string) []string {
+	lower := strings.ToLower(line)
+	var bad []string
+	r1 := false
+	for _, pat := range retiredPatterns {
+		if pat.MatchString(line) {
+			r1 = true
+		}
+	}
+	if r1 && !r1Prefilter(lower) {
+		bad = append(bad, "R1")
+	}
+	if (azureInfra.MatchString(line) || azureWord.MatchString(line)) && !r2Prefilter(lower) {
+		bad = append(bad, "R2")
+	}
+	if publishProduction.MatchString(line) && !r6Prefilter(line) {
+		bad = append(bad, "R6")
+	}
+	if overrideReasonRegex.MatchString(line) && !r4Prefilter(line) {
+		bad = append(bad, "R4")
+	}
+	return bad
+}
