+// pySplitLines mirrors Python's str.splitlines() (the oracle's line model).
+func pySplitLines(text string) []string {
+	// Fast path: plain "\n" text (the overwhelmingly common case) needs no rune walk.
+	if !strings.ContainsAny(text, "\r\v\f\x1c\x1d\x1e\^E\u2028\u2029") {
+		lines := strings.Split(text, "\n")
+		if n := len(lines); n > 0 && lines[n-1] == "" {
+			lines = lines[:n-1]
+		}
+		return lines
+	}
+	var lines []string
+	start := 0
+	rs := []rune(text)
+	for i := 0; i < len(rs); i++ {
+		switch rs[i] {
+		case '\n', '\v', '\f', '\x1c', '\x1d', '\x1e', '\x85', '\u2028', '\u2029':
+			lines = append(lines, string(rs[start:i]))
+			start = i + 1
+		case '\r':
+			lines = append(lines, string(rs[start:i]))
+			if i+1 < len(rs) && rs[i+1] == '\n' {
+				i++
+			}
+			start = i + 1
+		}
+	}
+	if start < len(rs) {
+		lines = append(lines, string(rs[start:]))
+	}
+	return lines
+}
+
+// pyLstripHash mirrors line.lstrip().startswith("#").
+func pyLstripHash(line string) bool {
+	return strings.HasPrefix(strings.TrimLeftFunc(line, unicode.IsSpace), "#")
+}
